#!/usr/bin/env node
// Build the React-based tools into self-contained HTML that runs with no network.
//
//   src/<name>.src.html  --(this script)-->  tools/<name>.html
//
// The source keeps React, ReactDOM and Babel as pinned, integrity-hashed unpkg tags and the app as <script type="text/babel">.
// The build downloads those three files once (cached in scripts/.cache, hash-checked against the integrity attributes in the
// source), compiles the JSX, and writes one HTML file with React, ReactDOM and the compiled app inlined. Nothing is fetched
// when the page loads, so a blocked or captive-portal network cannot blank it.
//
// usage: node scripts/build-react-tools.mjs [name ...]      (no names: build every src/*.src.html)
import { readFileSync, writeFileSync, existsSync, mkdirSync, readdirSync } from "node:fs";
import { createHash } from "node:crypto";
import { createRequire } from "node:module";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const cacheDir = join(root, "scripts", ".cache");
mkdirSync(cacheDir, { recursive: true });
const require = createRequire(import.meta.url);

async function fetchPinned(url, integrity) {
  const file = join(cacheDir, url.replace(/[^a-z0-9.@-]+/gi, "_"));
  let buf = existsSync(file) ? readFileSync(file) : null;
  if (!buf) {
    const res = await fetch(url);
    if (!res.ok) throw new Error(`fetch ${url}: HTTP ${res.status}`);
    buf = Buffer.from(await res.arrayBuffer());
    writeFileSync(file, buf);
  }
  const [algo, want] = integrity.split("-");
  const got = createHash(algo).update(buf).digest("base64");
  if (got !== want) throw new Error(`integrity mismatch for ${url}\n  want ${want}\n  got  ${got}`);
  return { buf, file };
}

const inline = (code) => code.replace(/<\/script/gi, "<\\/script").replace(/^\/\/# sourceMappingURL=.*$/gm, "");

async function build(name) {
  const srcPath = join(root, "src", `${name}.src.html`);
  const outPath = join(root, "tools", `${name}.html`);
  let html = readFileSync(srcPath, "utf8");
  // Any <script ... src="https://unpkg.com/..."></script>, whatever the attribute order or line breaks.
  const tagRe = /<script\b[^>]*\bsrc="(https:\/\/unpkg\.com\/[^"]+)"[^>]*>\s*<\/script>\n?/g;
  const libs = [...html.matchAll(tagRe)].map((m) => {
    const integrity = (m[0].match(/\bintegrity="([^"]+)"/) || [])[1];
    if (!integrity) throw new Error(`${name}: ${m[1]} has no integrity attribute; pin it before building`);
    return { tag: m[0], url: m[1], integrity };
  });
  const find = (frag) => libs.find((l) => l.url.includes(frag));
  const react = find("/react@"), dom = find("/react-dom@"), babel = find("/@babel/standalone@");
  if (!react || !dom || !babel) throw new Error(`${name}: expected pinned unpkg tags for react, react-dom and @babel/standalone`);

  const [r, d, b] = await Promise.all([react, dom, babel].map((l) => fetchPinned(l.url, l.integrity)));
  const Babel = require(b.file);

  const appRe = /<script type="text\/babel"[^>]*>([\s\S]*?)<\/script>/;
  const m = html.match(appRe);
  if (!m) throw new Error(`${name}: no <script type="text/babel"> block`);
  const compiled = Babel.transform(m[1], { presets: ["react"], sourceType: "script", compact: false, comments: false }).code;

  html = html.replace(react.tag, () => `<script>/* react ${react.url.split("@")[1].split("/")[0]} (production build, inlined; MIT) */\n${inline(r.buf.toString("utf8"))}\n</script>\n`);
  html = html.replace(dom.tag, () => `<script>/* react-dom ${dom.url.split("@")[1].split("/")[0]} (production build, inlined; MIT) */\n${inline(d.buf.toString("utf8"))}\n</script>\n`);
  html = html.replace(babel.tag, "");
  html = html.replace(appRe, () => `<script>\n${inline(compiled)}\n</script>`);
  html = html.replace(/<!doctype html>\n?/i, (x) => `${x}<!-- Built by scripts/build-react-tools.mjs from src/${name}.src.html. Edit the source file and rebuild; do not edit this file. -->\n`);
  if (/unpkg\.com/.test(html.replace(/\/\*[\s\S]*?\*\//g, "").replace(/unpkg\.com[^<]*<\/script/g, ""))) { /* source comments may mention it; checked below */ }
  writeFileSync(outPath, html);
  console.log(`built tools/${name}.html (${(html.length / 1024).toFixed(0)} KB)`);
}

const names = process.argv.slice(2);
const todo = names.length ? names : readdirSync(join(root, "src")).filter((f) => f.endsWith(".src.html")).map((f) => f.replace(/\.src\.html$/, ""));
for (const n of todo) await build(n);
